const STAGE = 'takeover';
const MAX_MINUTES = 60;
const BODY = "mkdir -p "$R/findings"
IN="$R/discovery/cname_hosts.txt"
: > nuclei.jsonl
if [ -s "$IN" ]; then
  timeout 60m nuclei -l "$IN" -tags takeover -dr -jsonl -silent -nc -duc -rl "$RATE" -o nuclei.jsonl >/dev/null 2>nuclei.log || true
  touch nuclei.jsonl
fi
python3 - "$ENG" nuclei.jsonl "$R/findings/takeover.jsonl" "$S" <<'PY'
import json, sys
eng, src, dst, evid = sys.argv[1:5]
out, seen = [], set()
for line in open(src):
    try:
        f = json.loads(line)
    except ValueError:
        continue
    host = (f.get("host") or "").split("://")[-1].split("/")[0].split(":")[0].lower()
    tid = f.get("template-id", "")
    key = f"{eng}|takeover|{tid}|{host}"
    if not host or key in seen:
        continue
    seen.add(key)
    info = f.get("info") or {}
    out.append({"finding_key": key, "source": "takeover", "host": host, "url": f.get("matched-at", ""),
                "template_id": tid, "name": info.get("name", ""), "severity": info.get("severity", "unknown"),
                "matched_at": f.get("matched-at", ""), "evidence_dir": evid,
                "detail": (info.get("description") or "")[:400]})
with open(dst, "w") as fh:
    for o in out:
        fh.write(json.dumps(o) + "\n")
print(json.dumps({"takeover_findings": len(out)}), file=open("result.json", "w"))
